 for r in receipt['retiredResources']:
  n=r['file']
  if r['before']!=manifest['files'][n]:raise ValueError('Retired resource predecessor differs')
  del expected['files'][n]
  if n in expected['localFiles']:expected['localFiles'].remove(n)
  slot,relative=n.split('/',1)
  for kind,lock in locks.items():
   target=next(x for x in lock['runtimes'] if x['destination']=='sherloq-browser/assets/'+slot)
   if target['files'].get(relative)!=r[kind+'BeforeSha256']:raise ValueError('Retired resource predecessor lock differs')
   target['files'].pop(relative,None)
 used={h for f in expected['files'].values() for h in f['chunks']}
 for h in receipt['retiredChunks']:
  if h in used or h not in expected['chunks']:raise ValueError('Invalid retired chunk')
  del expected['chunks'][h]
 if added!=receipt['manifest']['addedLocalFiles'] or encode(expected)!=verify(receipt['manifest']):raise ValueError('Undeclared native scope inventory change')
 for kind,lock in locks.items():
  if encode(lock)!=verify(receipt['locks'][kind]):raise ValueError('Undeclared native scope lock change')
 return receipt,previous
